+			continue
+		}
+		if !reflect.DeepEqual(currentValue.Field(index).Interface(), previousValue.Field(index).Interface()) {
+			name, _, _ := strings.Cut(field.Tag.Get("json"), ",")
+			if name == "" {
+				name = field.Name
+			}
+			fields = append(fields, name)
+		}
+	}
+	return fields
+}
