		fields = append(fields, "delivery")
	}
	if brief.Review != "" {
		fields = append(fields, "review")
	}
	if brief.Base != "" || len(brief.BaseByRepo) > 0 {
		fields = append(fields, "base")
	}
	if brief.Target != "" || len(brief.TargetByRepo) > 0 {
		fields = append(fields, "target")
	}
	if brief.Execution != "" {
