// ReviewVerdictsFor lists verdicts that remain valid for a Change Task, newest first.
func (db *DB) ReviewVerdictsFor(ctx context.Context, changeTaskID int64) ([]ReviewVerdict, error) {
	rows, err := db.QueryContext(ctx, `SELECT v.task_id FROM review_verdicts v JOIN tasks t ON t.id=v.task_id WHERE t.reviews_task_id=? AND NOT EXISTS(SELECT 1 FROM branch_author_invalidated_verdicts i WHERE i.task_id=v.task_id AND i.change_task_id=t.reviews_task_id) ORDER BY v.created_at DESC, v.task_id DESC`, changeTaskID)
	if err != nil {
		return nil, err
	}
	var ids []int64
	for rows.Next() {
		var id int64
		if err := rows.Scan(&id); err != nil {
			rows.Close()
			return nil, err
		}
		ids = append(ids, id)
	}
	if err := rows.Err(); err != nil {
		rows.Close()
		return nil, err
	}
	rows.Close()
	verdicts := make([]ReviewVerdict, 0, len(ids))
	for _, id := range ids {
		verdict, err := db.ReviewVerdict(ctx, id)
		if err != nil {
			return nil, err
		}
		verdicts = append(verdicts, verdict)
	}
	return verdicts, nil
}

// CurrentReviewPass returns the newest pass verdict of the Change Task whose
// bound targets equal its current candidate commits. A candidate that has
// moved has no current pass, and an older pass is never rebound to the new
// commits because targets are fixed when the Review Task is admitted.
func (db *DB) CurrentReviewPass(ctx context.Context, changeTaskID int64, candidate []ReviewTarget) (ReviewVerdict, bool, error) {
	verdicts, err := db.ReviewVerdictsFor(ctx, changeTaskID)
	if err != nil {
		return ReviewVerdict{}, false, err
	}
	for _, verdict := range verdicts {
		if verdict.Verdict != ReviewPass || !SameReviewTargets(verdict.Targets, candidate) {
			continue
		}
		return verdict, true, nil
	}
	return ReviewVerdict{}, false, nil
}

